def cantor_numbering(N: int) -> str:
    if N < 1:
        raise ValueError("N must be a positive integer")
    numerator, denominator = 1, 2
    for _ in range(N - 1):
        numerator, denominator = denominator, 2 * numerator - denominator
    return f'{numerator}/{denominator}'

