def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not n or not coeffs:
        return ""

    # Extract coefficients and their corresponding powers of x
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff != 0:
            power = i if i == n else i + 1
            # Format the term with the absolute value, x, or nothing
            term = f"{abs(coeff)}{f'{chr(97 + power)}^' if power > 1 else f'{chr(97 + power) if power == 1 else ''}"}
            terms.append(term if coeff > 0 else "+" + term)

    return ' '.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original) or len(encoded) != len(message) or len(original) == 0 or len(message) == 0:
        return "Failed"

    # Check if the original string is exhausted by the encoded string
    if len(original) < len(encoded):
        return "Failed"

    # Dictionary to store original and encoded characters
    mapping = {}

    # Mapping construction
    for i in range(len(encoded)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        else:
            if mapping[encoded[i]] != original[i]:
                return "Failed"

    # Check if all original characters are covered
    for char in original:
        if char not in mapping:
            return "Failed"

    # Decode the message
    decoded_message = ""
    for char in message:
        if char in mapping:
            decoded_message += mapping[char]
        else:
            return "Failed"

    return decoded_message

