def largest_prime_factor(n: int) -> int:
    # Handle edge cases
    if n <= 1:
        return None
    if n <= 3:
        return n
    if n % 2 == 0:
        return 2
    sqrt_n = int(math.sqrt(n))
    for divisor in range(3, sqrt_n + 1, 2):
        if n % divisor == 0:
            return n // divisor
    return n

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n < 1 or last < n:
        return 0  # Invalid input values
    if (n, last) in memo:
        return memo[(n, last)]  # Return from memoization

    # Recursive case: count sequences with the current number and the previous sequence
    memo[(n, last)] = 1 + count_sequences(n, n, memo)
    for i in range(1, min(n, last) // 2):
        memo[(n, last)] += count_sequences(n + i, last + i, memo)

    return memo[(n, last)]

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        raise ValueError("Both x0 and y0 must be positive integers.")

    count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        b = quotient // a
        if a * b == quotient and math.gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count

