def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be non-negative")
    catalan_values = [0] * (n + 1)
    catalan_values[0] = 1

    for i in range(1, n + 1):
        catalan_values[i] = sum(catalan_values[j] * catalan_values[i - 1 - j] for j in range(i // 2 + 1))

