def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Recursive function to return the maximum volume of the box that can be occupied by any subset of the given items
    def recursive_max_volume(index, remaining_volume):
        if index == n or remaining_volume == 0:
            return 0
        if volumes[index] > remaining_volume:
            # If the current item's volume is greater than the remaining volume, skip it
            return recursive_max_volume(index + 1, remaining_volume)
        # Choose to include the current item or skip it
        included = volumes[index] + recursive_max_volume(index + 1, remaining_volume - volumes[index])
        skipped = recursive_max_volume(index + 1, remaining_volume)
        return max(included, skipped)

    # Determine the maximum volume using the recursive function
    max_volume = recursive_max_volume(0, V)

    # Calculate the minimum remaining space
    min_remaining_space = V - max_volume
    return min_remaining_space

